// housing-ingest answers with ONE item carrying BOTH lists. Fan them out so a
// refused send costs one email rather than the whole pass.
const res = $input.first().json;
if (!res || res.ok !== true) {
  throw new Error('housing-ingest renewal_pending failed: ' + JSON.stringify(res).slice(0, 300));
}

const renewals = res.renewals || [];
const unknown = res.unknown_interval || [];

// Nothing due is the normal state on most days, and it is not a failure. A daily
// workflow that painted red on "nothing to renew" would be red all month and read
// by nobody — and then the one that mattered would look exactly like the others.
if (renewals.length === 0 && unknown.length === 0) {
  console.log('renewal guard: nothing due and no unknown rules');
  return [];
}
console.log('renewal guard: ' + renewals.length + ' due, ' + unknown.length + ' with an unknown rule');

// ⚠️ The two lists have DIFFERENT SHAPES, and that is load-bearing rather than an
// inconsistency: `unknown_interval` rows carry no `due_at` and no `days_left` at
// all, so no template can render one as though it were due on a date. (The brief
// this was first written against said the shapes matched. They do not.)
//
// The routing polarity fails LOUD. An item carrying a `due_at` is treated as a
// real deadline whichever array it arrived in, because a dated row rendered as
// "no rush" costs years of waiting-list seniority, while an undated row rendered
// urgently costs one over-urgent email.
const out = [];
for (const r of renewals) out.push({ json: { ...r, kind: 'renewal' } });
for (const u of unknown) out.push({ json: { ...u, kind: u.due_at ? 'renewal' : 'unknown' } });
return out;

__NOTIFY_JS__

// --- node body ---
// One email per row, built by the tested builders rather than by string
// concatenation here: list names, notes and both URLs are stored values that end
// up in an HTML body and a mail header.
//
// The recipient is the user's OWN inbox. Nothing in this pipeline ever contacts a
// waiting-list provider — the renewal itself is his to perform, and the confirm
// page is the only thing that records that he did.
const TO = $env.JOB_NOTIFY_TO || 'bastianrthomsen@gmail.com';
const now = new Date();

return $input.all().map((item) => {
  const row = item.json || {};
  const mail = row.kind === 'unknown'
    ? buildUnknownIntervalEmail(row, { now })
    : buildRenewalEmail(row, { now });
  return {
    json: {
      position_id: row.position_id,
      kind: row.kind,
      to: TO,
      subject: mail.subject,
      html: mail.html,
      // n8n's Gmail node sends a single body part, so only `html` is transmitted
      // today. `text` is the text/plain half a raw-MIME sender would attach, and
      // it is what the tests pin the email's CONTENT against independently of its
      // markup.
      text: mail.text,
    },
  };
});

__NOTIFY_JS__

// --- node body ---
// Reached only from the Gmail node's SUCCESS output.
//
// ⚠️ `renewal_result` stamps `last_reminded_at` — "we told him". It does NOT and
// must never touch `last_renewed_at` — "he did it". The two column names differ by
// four characters and mean opposite things; only a human POSTing on the
// `housing-renew` page can assert the second. Posting this for an email that never
// left would silence the guard for three days on a list that may have four days to
// live.
//
// `ok` is sent as a REAL BOOLEAN. The server parses it strictly and refuses to
// coerce, precisely so that a broken n8n expression evaluating to the string
// "false" cannot read as truthy.
//
// Pairing is by pairedItem, not by position: the error output pulls failed items
// out of this stream, so output-0 index i stops being upstream index i the moment
// one send fails, and that offset would stamp a message id onto the wrong list.
const composed = $('Build Renewal Email').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const sent = items[i].json || {};
  const src = composed[pairedSourceIndex(items[i].pairedItem, i)];
  const positionId = src && src.json ? src.json.position_id : null;

  // No id, no claim. Skipping leaves the row un-stamped, so tomorrow's pass
  // reminds again — the safe direction.
  if (!positionId) continue;

  out.push({
    json: {
      action: 'renewal_result',
      user_id: $env.NEXUS_USER_ID,
      position_id: positionId,
      ok: true,
      message_id: sent.id || sent.messageId || null,
    },
  });
}
return out;

// A failed send is not a failed run — but it must not be recorded as a success
// either, and here that is sharper than anywhere else in the pipeline.
//
// renewal_result is posted ONLY from the success output, so a row whose reminder
// did not leave the machine keeps its old `last_reminded_at` and tomorrow's pass
// picks it up again. That is the retry. Deliberately nothing is posted with
// `ok: false`: the server would accept it and log it, but the row must stay
// exactly as it was, and the daily schedule already provides the retry.
for (const item of $input.all()) {
  const j = item.json || {};
  const err = j.error || j.message || j;
  console.error(
    'RENEWAL REMINDER FAILED TO SEND — row left un-stamped for tomorrow: ' +
      JSON.stringify(err).slice(0, 300),
  );
}
return [];
